changeSet.sql:
DO $grants$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'smartmentor_metrics') THEN
        GRANT USAGE ON SCHEMA public TO smartmentor_metrics;
        GRANT SELECT ON assessment_items TO smartmentor_metrics;
    ELSE
        RAISE NOTICE 'Role smartmentor_metrics does not exist: grant skipped';
    END IF;
END
$grants$;

rollback.sql:
DO $revoke$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'smartmentor_metrics') THEN
        REVOKE SELECT ON assessment_items FROM smartmentor_metrics;
    END IF;
END
$revoke$;
